CREATE TABLE IF NOT EXISTS financial_cases(id uuid PRIMARY KEY, event_id text NOT NULL UNIQUE REFERENCES webhook_events(id), payment_id text REFERENCES payments(id), relationship_id uuid REFERENCES relationships(id), partner_id uuid REFERENCES partners(id), case_type text NOT NULL, amount_cents integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Needs review', details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolved_by uuid REFERENCES users(id), resolution_note text);
CREATE INDEX IF NOT EXISTS financial_cases_open ON financial_cases(status,created_at);
